impl Adopt {
    /// Maximum encoded bytes under these limits.
    #[must_use]
    pub fn encoded_bound(limits: &Limits) -> Option<u64> {
        if check_limits(limits).is_err() { return None; }
        Self::encoded_bound_within(limits)
    }

    pub(crate) fn encoded_bound_within(limits: &Limits) -> Option<u64> {
        let mut size = 0_u64;
        size = size.checked_add(4_u64)?.checked_add(1_u64)?;
        size = size.checked_add(2_u64)?.checked_add(4_u64.checked_add(u64::from(limits.adopt_owner))?)?;
        size = size.checked_add(4_u64.checked_add(u64::from(limits.adopt_name))?)?.checked_add(4_u64.checked_add(u64::from(limits.adopt_prefix))?)?;
        size = size.checked_add(Role::encoded_bound_within(limits)?)?.checked_add(4_u64.checked_add(u64::from(limits.adopt_landing))?)?;
        size = size.checked_add(1_u64)?.checked_add(4_u64.checked_add(u64::from(limits.adopt_checks).checked_mul(4_u64)?)?)?;
        size.checked_add(0)
    }

    /// Maximum heap held by one decoded value under these limits.
    #[must_use]
    pub fn decoded_bound(limits: &Limits) -> Option<u64> {
        if check_limits(limits).is_err() { return None; }
        Self::decoded_bound_within(limits)
    }

    pub(crate) fn decoded_bound_within(limits: &Limits) -> Option<u64> {
        let mut heap = 0_u64;
        heap = heap.checked_add(0_u64)?.checked_add(0_u64)?;
        heap = heap.checked_add(0_u64)?.checked_add(u64::from(limits.adopt_owner))?;
        heap = heap.checked_add(u64::from(limits.adopt_name))?.checked_add(u64::from(limits.adopt_prefix))?;
        heap = heap.checked_add(Role::decoded_bound_within(limits)?)?.checked_add(u64::from(limits.adopt_landing))?;
        heap = heap.checked_add(0_u64)?.checked_add(List::<u32>::price(limits.adopt_checks)?.checked_add(u64::from(limits.adopt_checks).checked_mul(0_u64)?)?)?;
        heap.checked_add(0)
    }
}

fn adopt_encoded_bound_family(limits: &Limits, biggest: u64) -> Option<u64> {
    let biggest = biggest.max(Adopt::encoded_bound_within(limits)?);
    kept_encoded_bound_family(limits, biggest)
}

fn adopt_decoded_bound_family(limits: &Limits, biggest: u64) -> Option<u64> {
    let biggest = biggest.max(Adopt::decoded_bound_within(limits)?);
    kept_decoded_bound_family(limits, biggest)
}

fn check_adopt_record_limits(limits: &Limits) -> Result<(), Problem> {
    if limits.adopt_owner > CEILINGS.adopt_owner { return Err(Problem { path: Path::AdoptOwner, reason: skein_codec::Reason::Bound }); }
    if limits.adopt_name > CEILINGS.adopt_name { return Err(Problem { path: Path::AdoptName, reason: skein_codec::Reason::Bound }); }
    if limits.adopt_prefix > CEILINGS.adopt_prefix { return Err(Problem { path: Path::AdoptPrefix, reason: skein_codec::Reason::Bound }); }
    if limits.adopt_landing > CEILINGS.adopt_landing { return Err(Problem { path: Path::AdoptLanding, reason: skein_codec::Reason::Bound }); }
    if limits.adopt_checks > CEILINGS.adopt_checks { return Err(Problem { path: Path::AdoptChecks, reason: skein_codec::Reason::Bound }); }
    check_managed_forge_record_limits(limits)
}

