// Type: Role.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum Role {
    Owned,
    Adopted,
    Fork,
    Context,
}

// Record: Role.
impl Record for Role {
    type Limits = Limits;
    const TAIL: Path = paths::ROLE_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 4)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 4)?.decoded)
    }

    fn write(&self, _limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Owned => field::put(out, &[0], paths::ROLE_TAG),
            Self::Adopted => field::put(out, &[1], paths::ROLE_TAG),
            Self::Fork => field::put(out, &[2], paths::ROLE_TAG),
            Self::Context => field::put(out, &[3], paths::ROLE_TAG),
        }
    }

    fn read(_limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::ROLE_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Owned),
            1 => Ok(Self::Adopted),
            2 => Ok(Self::Fork),
            3 => Ok(Self::Context),
            4..=u8::MAX => Err(Problem { path: paths::ROLE_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

// Type: Adopt.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct Adopt {
    pub project: u32,
    pub home: bool,
    pub forge: u16,
    pub owner: Box<[u8]>,
    pub name: Box<[u8]>,
    pub prefix: Box<[u8]>,
    pub role: Role,
    pub landing: Box<[u8]>,
    pub ci: bool,
    pub checks: List<u32>,
}

// Record: Adopt.
impl Record for Adopt {
    type Limits = Limits;
    const TAIL: Path = paths::ADOPT_TAIL;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 15)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 15)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        field::write(field::U32, &self.project, limits, out, paths::ADOPT_PROJECT)?;
        field::write(field::Boolean, &self.home, limits, out, paths::ADOPT_HOME)?;
        field::write(field::U16, &self.forge, limits, out, paths::ADOPT_FORGE)?;
        field::write(field::Bytes { limit: limits.adopt_owner.min(CEILINGS.adopt_owner) }, &self.owner, limits, out, paths::ADOPT_OWNER)?;
        field::write(field::Bytes { limit: limits.adopt_name.min(CEILINGS.adopt_name) }, &self.name, limits, out, paths::ADOPT_NAME)?;
        field::write(field::Bytes { limit: limits.adopt_prefix.min(CEILINGS.adopt_prefix) }, &self.prefix, limits, out, paths::ADOPT_PREFIX)?;
        field::write(field::Nested, &self.role, limits, out, paths::ADOPT_ROLE)?;
        field::write(field::Bytes { limit: limits.adopt_landing.min(CEILINGS.adopt_landing) }, &self.landing, limits, out, paths::ADOPT_LANDING)?;
        field::write(field::Boolean, &self.ci, limits, out, paths::ADOPT_CI)?;
        field::write(field::Sequence { limit: limits.adopt_checks.min(CEILINGS.adopt_checks), minimum: 4, item: field::U32 }, &self.checks, limits, out, paths::ADOPT_CHECKS)?;
        Ok(())
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        Ok(Self {
            project: field::read(field::U32, limits, reader, paths::ADOPT_PROJECT)?,
            home: field::read(field::Boolean, limits, reader, paths::ADOPT_HOME)?,
            forge: field::read(field::U16, limits, reader, paths::ADOPT_FORGE)?,
            owner: field::read(field::Bytes { limit: limits.adopt_owner.min(CEILINGS.adopt_owner) }, limits, reader, paths::ADOPT_OWNER)?,
            name: field::read(field::Bytes { limit: limits.adopt_name.min(CEILINGS.adopt_name) }, limits, reader, paths::ADOPT_NAME)?,
            prefix: field::read(field::Bytes { limit: limits.adopt_prefix.min(CEILINGS.adopt_prefix) }, limits, reader, paths::ADOPT_PREFIX)?,
            role: field::read(field::Nested, limits, reader, paths::ADOPT_ROLE)?,
            landing: field::read(field::Bytes { limit: limits.adopt_landing.min(CEILINGS.adopt_landing) }, limits, reader, paths::ADOPT_LANDING)?,
            ci: field::read(field::Boolean, limits, reader, paths::ADOPT_CI)?,
            checks: field::read(field::Sequence { limit: limits.adopt_checks.min(CEILINGS.adopt_checks), minimum: 4, item: field::U32 }, limits, reader, paths::ADOPT_CHECKS)?,
        })
    }
}

