pub struct Trials {
    pub rows: List<TrialRow>,
}

// Record: Trials.
impl Record for Trials {
    type Limits = Limits;
    const TAIL: Path = paths::TRIALS_TAIL;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 107)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 107)?.decoded)
    }

    #[cfg(debug_assertions)]
    fn decode(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let value = Self::read(limits, reader)?;
        if !reader.is_empty() {
            return Err(Self::TAIL.problem(skein_codec::Reason::Trailing));
        }
        Ok(value)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        field::put(out, &VERSION.to_be_bytes(), paths::TRIALS_VERSION)?;
        field::write(field::Sequence { limit: limits.trials_rows.min(CEILINGS.trials_rows), minimum: 9, item: field::Nested }, &self.rows, limits, out, paths::TRIALS_ROWS)?;
        Ok(())
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        field::version(reader, VERSION, paths::TRIALS_VERSION)?;
        Ok(Self {
            rows: field::read(field::Sequence { limit: limits.trials_rows.min(CEILINGS.trials_rows), minimum: 9, item: field::Nested }, limits, reader, paths::TRIALS_ROWS)?,
        })
    }
}

