// Type: DraftChange.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum DraftChange {
    Ready(ReadyDraft),
    NotReady,
    Started(StartedDraft),
}

// Record: DraftChange.
impl Record for DraftChange {
    type Limits = Limits;
    const TAIL: Path = paths::DRAFT_CHANGE_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 321)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 321)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Ready(value) => { field::put(out, &[0], paths::DRAFT_CHANGE_TAG)?; value.write(limits, out) },
            Self::NotReady => field::put(out, &[1], paths::DRAFT_CHANGE_TAG),
            Self::Started(value) => { field::put(out, &[2], paths::DRAFT_CHANGE_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::DRAFT_CHANGE_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Ready(ReadyDraft::read(limits, reader)?)),
            1 => Ok(Self::NotReady),
            2 => Ok(Self::Started(StartedDraft::read(limits, reader)?)),
            3..=u8::MAX => Err(Problem { path: paths::DRAFT_CHANGE_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

