// Type: Requesting.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct Requesting {
    pub request: Request,
}

// Record: Requesting.
impl Record for Requesting {
    type Limits = Limits;
    const TAIL: Path = paths::REQUESTING_TAIL;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 470)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 470)?.decoded)
    }

    #[cfg(debug_assertions)]
    fn decode(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let value = Self::read(limits, reader)?;
        if !reader.is_empty() {
            return Err(Self::TAIL.problem(skein_codec::Reason::Trailing));
        }
        Ok(value)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        field::put(out, &VERSION.to_be_bytes(), paths::REQUESTING_VERSION)?;
        field::write(field::Nested, &self.request, limits, out, paths::REQUESTING_REQUEST)?;
        Ok(())
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        field::version(reader, VERSION, paths::REQUESTING_VERSION)?;
        Ok(Self {
            request: field::read(field::Nested, limits, reader, paths::REQUESTING_REQUEST)?,
        })
    }
}

