// Type: Forges.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct Forges {
    pub forges: List<ForgeRow>,
    pub linked: bool,
}

// Record: Forges.
impl Record for Forges {
    type Limits = Limits;
    const TAIL: Path = paths::FORGES_TAIL;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 628)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 628)?.decoded)
    }

    #[cfg(debug_assertions)]
    fn decode(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let value = Self::read(limits, reader)?;
        if !reader.is_empty() {
            return Err(Self::TAIL.problem(skein_codec::Reason::Trailing));
        }
        Ok(value)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        field::put(out, &VERSION.to_be_bytes(), paths::FORGES_VERSION)?;
        field::write(field::Sequence { limit: limits.forges_forges.min(CEILINGS.forges_forges), minimum: 31, item: field::Nested }, &self.forges, limits, out, paths::FORGES_FORGES)?;
        field::write(field::Boolean, &self.linked, limits, out, paths::FORGES_LINKED)?;
        Ok(())
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        field::version(reader, VERSION, paths::FORGES_VERSION)?;
        Ok(Self {
            forges: field::read(field::Sequence { limit: limits.forges_forges.min(CEILINGS.forges_forges), minimum: 31, item: field::Nested }, limits, reader, paths::FORGES_FORGES)?,
            linked: field::read(field::Boolean, limits, reader, paths::FORGES_LINKED)?,
        })
    }
}

