// Type: View.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum View {
    Way(WayView),
    Path(BranchPath),
    Proposal(ProposalView),
    Charter(CharterView),
    Rule(RuleView),
    Roles(RolesView),
    NotDrawn(NotDrawn),
}

// Record: View.
impl Record for View {
    type Limits = Limits;
    const TAIL: Path = paths::VIEW_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 765)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 765)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Way(value) => { field::put(out, &[0], paths::VIEW_TAG)?; value.write(limits, out) },
            Self::Path(value) => { field::put(out, &[1], paths::VIEW_TAG)?; value.write(limits, out) },
            Self::Proposal(value) => { field::put(out, &[2], paths::VIEW_TAG)?; value.write(limits, out) },
            Self::Charter(value) => { field::put(out, &[3], paths::VIEW_TAG)?; value.write(limits, out) },
            Self::Rule(value) => { field::put(out, &[4], paths::VIEW_TAG)?; value.write(limits, out) },
            Self::Roles(value) => { field::put(out, &[5], paths::VIEW_TAG)?; value.write(limits, out) },
            Self::NotDrawn(value) => { field::put(out, &[6], paths::VIEW_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::VIEW_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Way(WayView::read(limits, reader)?)),
            1 => Ok(Self::Path(BranchPath::read(limits, reader)?)),
            2 => Ok(Self::Proposal(ProposalView::read(limits, reader)?)),
            3 => Ok(Self::Charter(CharterView::read(limits, reader)?)),
            4 => Ok(Self::Rule(RuleView::read(limits, reader)?)),
            5 => Ok(Self::Roles(RolesView::read(limits, reader)?)),
            6 => Ok(Self::NotDrawn(NotDrawn::read(limits, reader)?)),
            7..=u8::MAX => Err(Problem { path: paths::VIEW_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

// Type: ViewAnswer.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct ViewAnswer {
    pub view: View,
}

// Record: ViewAnswer.
impl Record for ViewAnswer {
    type Limits = Limits;
    const TAIL: Path = paths::VIEW_ANSWER_TAIL;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 766)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 766)?.decoded)
    }

    #[cfg(debug_assertions)]
    fn decode(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let value = Self::read(limits, reader)?;
        if !reader.is_empty() {
            return Err(Self::TAIL.problem(skein_codec::Reason::Trailing));
        }
        Ok(value)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        field::put(out, &VERSION.to_be_bytes(), paths::VIEW_ANSWER_VERSION)?;
        field::write(field::Nested, &self.view, limits, out, paths::VIEW_ANSWER_VIEW)?;
        Ok(())
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        field::version(reader, VERSION, paths::VIEW_ANSWER_VERSION)?;
        Ok(Self {
            view: field::read(field::Nested, limits, reader, paths::VIEW_ANSWER_VIEW)?,
        })
    }
}

