// Type: Read.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum Read {
    Playground,
    Setting(SettingRead),
    ProposalItems(ProposalItemsRead),
    Deployment,
    RevisionSetting(RevisionSettingRead),
    ProgramEnvironment,
    View(ViewRead),
    Finding(FindingRead),
    History(HistoryRead),
    Milestone(MilestoneRead),
    Limits(LimitsRead),
    LimitHolds(LimitHoldsRead),
}

// Record: Read.
impl Record for Read {
    type Limits = Limits;
    const TAIL: Path = paths::READ_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1084)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1084)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Playground => field::put(out, &[0], paths::READ_TAG),
            Self::Setting(value) => { field::put(out, &[1], paths::READ_TAG)?; value.write(limits, out) },
            Self::ProposalItems(value) => { field::put(out, &[2], paths::READ_TAG)?; value.write(limits, out) },
            Self::Deployment => field::put(out, &[3], paths::READ_TAG),
            Self::RevisionSetting(value) => { field::put(out, &[4], paths::READ_TAG)?; value.write(limits, out) },
            Self::ProgramEnvironment => field::put(out, &[5], paths::READ_TAG),
            Self::View(value) => { field::put(out, &[6], paths::READ_TAG)?; value.write(limits, out) },
            Self::Finding(value) => { field::put(out, &[7], paths::READ_TAG)?; value.write(limits, out) },
            Self::History(value) => { field::put(out, &[8], paths::READ_TAG)?; value.write(limits, out) },
            Self::Milestone(value) => { field::put(out, &[9], paths::READ_TAG)?; value.write(limits, out) },
            Self::Limits(value) => { field::put(out, &[10], paths::READ_TAG)?; value.write(limits, out) },
            Self::LimitHolds(value) => { field::put(out, &[11], paths::READ_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::READ_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Playground),
            1 => Ok(Self::Setting(SettingRead::read(limits, reader)?)),
            2 => Ok(Self::ProposalItems(ProposalItemsRead::read(limits, reader)?)),
            3 => Ok(Self::Deployment),
            4 => Ok(Self::RevisionSetting(RevisionSettingRead::read(limits, reader)?)),
            5 => Ok(Self::ProgramEnvironment),
            6 => Ok(Self::View(ViewRead::read(limits, reader)?)),
            7 => Ok(Self::Finding(FindingRead::read(limits, reader)?)),
            8 => Ok(Self::History(HistoryRead::read(limits, reader)?)),
            9 => Ok(Self::Milestone(MilestoneRead::read(limits, reader)?)),
            10 => Ok(Self::Limits(LimitsRead::read(limits, reader)?)),
            11 => Ok(Self::LimitHolds(LimitHoldsRead::read(limits, reader)?)),
            12..=u8::MAX => Err(Problem { path: paths::READ_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

