// Type: Watch.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum Watch {
    Change(ChangeSubject),
    Forges,
    Landing(LandingSubject),
    Landings(LandingsSubject),
    Dismissed,
    Changes(ChangesSubject),
    Status(StatusSubject),
    Away,
    Decided(DecidedSubject),
    Trials,
    Approvals,
    Ways(WaysSubject),
    Drafts(DraftsSubject),
    Follows(FollowsSubject),
    Devices,
    Findings(FindingsSubject),
}

// Record: Watch.
impl Record for Watch {
    type Limits = Limits;
    const TAIL: Path = paths::WATCH_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1132)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1132)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Change(value) => { field::put(out, &[0], paths::WATCH_TAG)?; value.write(limits, out) },
            Self::Forges => field::put(out, &[1], paths::WATCH_TAG),
            Self::Landing(value) => { field::put(out, &[2], paths::WATCH_TAG)?; value.write(limits, out) },
            Self::Landings(value) => { field::put(out, &[3], paths::WATCH_TAG)?; value.write(limits, out) },
            Self::Dismissed => field::put(out, &[4], paths::WATCH_TAG),
            Self::Changes(value) => { field::put(out, &[5], paths::WATCH_TAG)?; value.write(limits, out) },
            Self::Status(value) => { field::put(out, &[6], paths::WATCH_TAG)?; value.write(limits, out) },
            Self::Away => field::put(out, &[7], paths::WATCH_TAG),
            Self::Decided(value) => { field::put(out, &[8], paths::WATCH_TAG)?; value.write(limits, out) },
            Self::Trials => field::put(out, &[9], paths::WATCH_TAG),
            Self::Approvals => field::put(out, &[10], paths::WATCH_TAG),
            Self::Ways(value) => { field::put(out, &[11], paths::WATCH_TAG)?; value.write(limits, out) },
            Self::Drafts(value) => { field::put(out, &[12], paths::WATCH_TAG)?; value.write(limits, out) },
            Self::Follows(value) => { field::put(out, &[13], paths::WATCH_TAG)?; value.write(limits, out) },
            Self::Devices => field::put(out, &[14], paths::WATCH_TAG),
            Self::Findings(value) => { field::put(out, &[15], paths::WATCH_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::WATCH_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Change(ChangeSubject::read(limits, reader)?)),
            1 => Ok(Self::Forges),
            2 => Ok(Self::Landing(LandingSubject::read(limits, reader)?)),
            3 => Ok(Self::Landings(LandingsSubject::read(limits, reader)?)),
            4 => Ok(Self::Dismissed),
            5 => Ok(Self::Changes(ChangesSubject::read(limits, reader)?)),
            6 => Ok(Self::Status(StatusSubject::read(limits, reader)?)),
            7 => Ok(Self::Away),
            8 => Ok(Self::Decided(DecidedSubject::read(limits, reader)?)),
            9 => Ok(Self::Trials),
            10 => Ok(Self::Approvals),
            11 => Ok(Self::Ways(WaysSubject::read(limits, reader)?)),
            12 => Ok(Self::Drafts(DraftsSubject::read(limits, reader)?)),
            13 => Ok(Self::Follows(FollowsSubject::read(limits, reader)?)),
            14 => Ok(Self::Devices),
            15 => Ok(Self::Findings(FindingsSubject::read(limits, reader)?)),
            16..=u8::MAX => Err(Problem { path: paths::WATCH_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

