// Type: Proof.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum Proof {
    Unkeyed,
    Keyed,
    Dispatched(Dispatched),
    Waiting,
    Passed(Receipted),
    Failed(Receipted),
}

// Record: Proof.
impl Record for Proof {
    type Limits = Limits;
    const TAIL: Path = paths::PROOF_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1153)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1153)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Unkeyed => field::put(out, &[0], paths::PROOF_TAG),
            Self::Keyed => field::put(out, &[1], paths::PROOF_TAG),
            Self::Dispatched(value) => { field::put(out, &[2], paths::PROOF_TAG)?; value.write(limits, out) },
            Self::Waiting => field::put(out, &[3], paths::PROOF_TAG),
            Self::Passed(value) => { field::put(out, &[4], paths::PROOF_TAG)?; value.write(limits, out) },
            Self::Failed(value) => { field::put(out, &[5], paths::PROOF_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::PROOF_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Unkeyed),
            1 => Ok(Self::Keyed),
            2 => Ok(Self::Dispatched(Dispatched::read(limits, reader)?)),
            3 => Ok(Self::Waiting),
            4 => Ok(Self::Passed(Receipted::read(limits, reader)?)),
            5 => Ok(Self::Failed(Receipted::read(limits, reader)?)),
            6..=u8::MAX => Err(Problem { path: paths::PROOF_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

