// Type: SearchTests.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum SearchTests {
    Whole,
    ByTest(SearchByTest),
    WholeAgain,
}

// Record: SearchTests.
impl Record for SearchTests {
    type Limits = Limits;
    const TAIL: Path = paths::SEARCH_TESTS_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1224)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1224)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Whole => field::put(out, &[0], paths::SEARCH_TESTS_TAG),
            Self::ByTest(value) => { field::put(out, &[1], paths::SEARCH_TESTS_TAG)?; value.write(limits, out) },
            Self::WholeAgain => field::put(out, &[2], paths::SEARCH_TESTS_TAG),
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::SEARCH_TESTS_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Whole),
            1 => Ok(Self::ByTest(SearchByTest::read(limits, reader)?)),
            2 => Ok(Self::WholeAgain),
            3..=u8::MAX => Err(Problem { path: paths::SEARCH_TESTS_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

