// Type: LandingWaitFor.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum LandingWaitFor {
    Nothing,
    Release,
    Ready,
    Turn,
    Prepare,
    Prefixes,
    Open,
    Close,
    Delete,
    Post,
    Run,
    Receipt,
    Judgement,
    Merge,
    Record,
    Ancestry,
    Read,
    Room,
}

// Record: LandingWaitFor.
impl Record for LandingWaitFor {
    type Limits = Limits;
    const TAIL: Path = paths::LANDING_WAIT_FOR_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1310)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1310)?.decoded)
    }

    fn write(&self, _limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Nothing => field::put(out, &[0], paths::LANDING_WAIT_FOR_TAG),
            Self::Release => field::put(out, &[1], paths::LANDING_WAIT_FOR_TAG),
            Self::Ready => field::put(out, &[2], paths::LANDING_WAIT_FOR_TAG),
            Self::Turn => field::put(out, &[3], paths::LANDING_WAIT_FOR_TAG),
            Self::Prepare => field::put(out, &[4], paths::LANDING_WAIT_FOR_TAG),
            Self::Prefixes => field::put(out, &[5], paths::LANDING_WAIT_FOR_TAG),
            Self::Open => field::put(out, &[6], paths::LANDING_WAIT_FOR_TAG),
            Self::Close => field::put(out, &[7], paths::LANDING_WAIT_FOR_TAG),
            Self::Delete => field::put(out, &[8], paths::LANDING_WAIT_FOR_TAG),
            Self::Post => field::put(out, &[9], paths::LANDING_WAIT_FOR_TAG),
            Self::Run => field::put(out, &[10], paths::LANDING_WAIT_FOR_TAG),
            Self::Receipt => field::put(out, &[11], paths::LANDING_WAIT_FOR_TAG),
            Self::Judgement => field::put(out, &[12], paths::LANDING_WAIT_FOR_TAG),
            Self::Merge => field::put(out, &[13], paths::LANDING_WAIT_FOR_TAG),
            Self::Record => field::put(out, &[14], paths::LANDING_WAIT_FOR_TAG),
            Self::Ancestry => field::put(out, &[15], paths::LANDING_WAIT_FOR_TAG),
            Self::Read => field::put(out, &[16], paths::LANDING_WAIT_FOR_TAG),
            Self::Room => field::put(out, &[17], paths::LANDING_WAIT_FOR_TAG),
        }
    }

    fn read(_limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::LANDING_WAIT_FOR_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Nothing),
            1 => Ok(Self::Release),
            2 => Ok(Self::Ready),
            3 => Ok(Self::Turn),
            4 => Ok(Self::Prepare),
            5 => Ok(Self::Prefixes),
            6 => Ok(Self::Open),
            7 => Ok(Self::Close),
            8 => Ok(Self::Delete),
            9 => Ok(Self::Post),
            10 => Ok(Self::Run),
            11 => Ok(Self::Receipt),
            12 => Ok(Self::Judgement),
            13 => Ok(Self::Merge),
            14 => Ok(Self::Record),
            15 => Ok(Self::Ancestry),
            16 => Ok(Self::Read),
            17 => Ok(Self::Room),
            18..=u8::MAX => Err(Problem { path: paths::LANDING_WAIT_FOR_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

