// Type: Protection.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum Protection {
    Unknown,
    Absent,
    Rule(Rule),
}

// Record: Protection.
impl Record for Protection {
    type Limits = Limits;
    const TAIL: Path = paths::PROTECTION_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1566)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1566)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Unknown => field::put(out, &[0], paths::PROTECTION_TAG),
            Self::Absent => field::put(out, &[1], paths::PROTECTION_TAG),
            Self::Rule(value) => { field::put(out, &[2], paths::PROTECTION_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::PROTECTION_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Unknown),
            1 => Ok(Self::Absent),
            2 => Ok(Self::Rule(Rule::read(limits, reader)?)),
            3..=u8::MAX => Err(Problem { path: paths::PROTECTION_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

