// Type: CheckpointWhy.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum CheckpointWhy {
    NotOwner,
    InProgress,
    Unavailable,
    Files,
    Unrecognized(CheckpointPath),
    Vanished(CheckpointPath),
    Failed(CheckpointFailed),
}

// Record: CheckpointWhy.
impl Record for CheckpointWhy {
    type Limits = Limits;
    const TAIL: Path = paths::CHECKPOINT_WHY_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1644)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1644)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::NotOwner => field::put(out, &[0], paths::CHECKPOINT_WHY_TAG),
            Self::InProgress => field::put(out, &[1], paths::CHECKPOINT_WHY_TAG),
            Self::Unavailable => field::put(out, &[2], paths::CHECKPOINT_WHY_TAG),
            Self::Files => field::put(out, &[3], paths::CHECKPOINT_WHY_TAG),
            Self::Unrecognized(value) => { field::put(out, &[4], paths::CHECKPOINT_WHY_TAG)?; value.write(limits, out) },
            Self::Vanished(value) => { field::put(out, &[5], paths::CHECKPOINT_WHY_TAG)?; value.write(limits, out) },
            Self::Failed(value) => { field::put(out, &[6], paths::CHECKPOINT_WHY_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::CHECKPOINT_WHY_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::NotOwner),
            1 => Ok(Self::InProgress),
            2 => Ok(Self::Unavailable),
            3 => Ok(Self::Files),
            4 => Ok(Self::Unrecognized(CheckpointPath::read(limits, reader)?)),
            5 => Ok(Self::Vanished(CheckpointPath::read(limits, reader)?)),
            6 => Ok(Self::Failed(CheckpointFailed::read(limits, reader)?)),
            7..=u8::MAX => Err(Problem { path: paths::CHECKPOINT_WHY_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

