// Type: Oversized.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum Oversized {
    Fail,
    Drop,
}

// Record: Oversized.
impl Record for Oversized {
    type Limits = Limits;
    const TAIL: Path = paths::OVERSIZED_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1875)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1875)?.decoded)
    }

    fn write(&self, _limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Fail => field::put(out, &[0], paths::OVERSIZED_TAG),
            Self::Drop => field::put(out, &[1], paths::OVERSIZED_TAG),
        }
    }

    fn read(_limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::OVERSIZED_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Fail),
            1 => Ok(Self::Drop),
            2..=u8::MAX => Err(Problem { path: paths::OVERSIZED_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

